<script setup>
import {onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import BaseButton from '../../components/ui/BaseButton.vue'
import {referenceIdTypeService} from '../../services/referenceIdTypeService'
const route=useRoute(),router=useRouter(),isEdit=!!route.params.code,loading=ref(false),saving=ref(false),errorMessage=ref('')
const form=reactive({code:'',display_label:'',is_active:true})
async function load(){if(!isEdit)return;loading.value=true;try{const res=await referenceIdTypeService.get(route.params.code),row=res?.data||res;form.code=row.code||route.params.code;form.display_label=row.display_label||'';form.is_active=Boolean(row.is_active)}catch(e){errorMessage.value=e?.message||'Unable to load reference ID type.'}finally{loading.value=false}}
async function save(){errorMessage.value='';if(!form.code.trim()||!form.display_label.trim()){errorMessage.value='Code and display label are required.';return}saving.value=true;try{const payload={display_label:form.display_label.trim(),is_active:Boolean(form.is_active)};if(isEdit)await referenceIdTypeService.update(route.params.code,payload);else await referenceIdTypeService.create({code:form.code.trim().toUpperCase(),...payload});router.push('/reference-id-types')}catch(e){errorMessage.value=e?.message||'Unable to save reference ID type.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><section class="module-page"><div class="module-page-intro"><div><h2>{{isEdit?'Edit Reference ID Type':'Add Reference ID Type'}}</h2><p class="module-description">Maintain the ID type code, display label, and active status.</p></div><BaseButton variant="secondary" @click="router.push('/reference-id-types')">← Back to ID types</BaseButton></div><section class="module-panel module-form-panel"><div class="module-panel-header"><h3>Reference ID type information</h3></div><p v-if="loading" class="module-description" style="padding:16px 24px">Loading type…</p><form v-else @submit.prevent="save"><div class="module-form-grid"><label class="module-form-field"><span>Code *</span><input v-model="form.code" class="ui-input" placeholder="PASSPORT" required :disabled="isEdit" /></label><label class="module-form-field"><span>Display label *</span><input v-model="form.display_label" class="ui-input" placeholder="Passport" required /></label><label class="module-form-field" style="flex-direction:row;align-items:center;gap:10px"><input v-model="form.is_active" type="checkbox" style="width:auto;min-height:0" /><span>Active</span></label></div><p v-if="errorMessage" role="alert" style="margin:0 24px 16px;color:#b43f4a">{{errorMessage}}</p><div class="module-form-footer"><span>Code cannot be changed after creation.</span><div><BaseButton type="button" variant="secondary" @click="router.push('/reference-id-types')">Cancel</BaseButton><BaseButton type="submit" :disabled="saving||loading">{{saving?'Saving…':isEdit?'Save changes':'Create type'}}</BaseButton></div></div></form></section></section></template>
